import React from 'react';
import { Typography, Button } from 'antd';
import { LeftOutlined, RightOutlined } from '@ant-design/icons';
import { 
  getFirstDayOfMonth, 
  getDaysInMonth, 
  formatDate,
  isDateInRange
} from '../utils/calendarHelpers';

const { Title } = Typography;

const CalendarGrid = ({
  currentYear,
  currentMonth,
  goToPrevMonth,
  goToNextMonth,
  selectionStart,
  selectionEnd,
  handleDateClick,
  handlePageChange,
  renderAvailabilityBadges,
  shouldRenderDate,
  currentRoute
}) => {
  // Month names array
  const monthNames = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];

  // Day labels
  const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

  // Get number of days in month and the day of week for the first day
  const daysInMonth = getDaysInMonth(currentYear, currentMonth);
  const firstDayOfMonth = getFirstDayOfMonth(currentYear, currentMonth);

  // Calculate empty cells at the beginning of the month
  const emptyCells = Array(firstDayOfMonth).fill(null);

  // Create array of day numbers for the current month
  const daysArray = Array.from({ length: daysInMonth }, (_, i) => i + 1);

  return (
    <div className="calendar-container">
      {/* Calendar header with navigation */}
      <div className="calendar-header">
        <Button 
          type="text" 
          icon={<LeftOutlined />} 
          onClick={goToPrevMonth} 
          className="nav-button"
        />
        <Title level={4} className="month-title">
          {monthNames[currentMonth]} {currentYear}
        </Title>
        <Button 
          type="text" 
          icon={<RightOutlined />} 
          onClick={goToNextMonth} 
          className="nav-button"
        />
      </div>

      {/* Day names header */}
      <div className="calendar-grid">
        {days.map(day => (
          <div key={day} className="day-header">
            {day}
          </div>
        ))}

        {/* Empty cells for days before the first of the month */}
        {emptyCells.map((_, index) => (
          <div key={`empty-${index}`} className="day-cell empty"></div>
        ))}

        {/* Day cells with availability data */}
        {daysArray.map(day => {
          const dateString = formatDate(currentYear, currentMonth, day);
          const isInRange = isDateInRange(dateString, selectionStart, selectionEnd);
          const isStart = dateString === selectionStart;
          const isEnd = dateString === selectionEnd;

          // Check if we should render this date based on filters
          if (!shouldRenderDate(dateString)) {
            return (
              <div 
                key={day} 
                className={`day-cell filtered-out ${isInRange ? 'in-range' : ''} ${isStart ? 'range-start' : ''} ${isEnd ? 'range-end' : ''}`}
                onClick={() => handleDateClick(dateString)}
              >
                <div className="date-number">{day}</div>
                <div className="filtered-overlay">Filtered</div>
              </div>
            );
          }

          return (
            <div 
              key={day} 
              className={`day-cell ${isInRange ? 'in-range' : ''} ${isStart ? 'range-start' : ''} ${isEnd ? 'range-end' : ''}`}
              onClick={() => handleDateClick(dateString)}
            >
              <div className="date-number">{day}</div>
              {/* Render availability badges for each class */}
              <div className="availability-container">
                {currentRoute && (
                  <div className="availability-badges">
                    {renderAvailabilityBadges(
                      currentRoute, 
                      ['Y', 'W', 'J', 'F'], 
                      dateString
                    )}
                  </div>
                )}
              </div>

              {/* Pagination arrows if needed */}
              <div className="pagination-arrows">
                <span 
                  className="page-arrow prev-page" 
                  onClick={(e) => handlePageChange(dateString, 'prev', e)}
                >
                  &#10094;
                </span>
                <span 
                  className="page-arrow next-page" 
                  onClick={(e) => handlePageChange(dateString, 'next', e)}
                >
                  &#10095;
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default CalendarGrid;
